```javascript
import * as THREE from 'three/webgpu';
import { texture, uniform, uv, vec2, vec3, mix, float } from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-quote-panel';
  group.position.set(2.5, 0.7, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const colors = {
    ink: new THREE.Color('#16161d'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38'),
    surface: new THREE.Color('#0b0b10'),
  };

  const width = 2.0;
  const height = (320 / 512) * width;

  const geometry = new THREE.PlaneGeometry(width, height);

  const tex = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  tex.colorSpace = THREE.SRGBColorSpace;

  const hoverUniform = uniform(0);
  const focusUniform = uniform(0);

  const material = new THREE.MeshStandardNodeMaterial();
  material.metalness = 0.4;
  material.roughness = 0.6;
  material.clearcoat = 0.2;

  const baseTex = texture(tex, uv());
  const accentEdge = mix(vec3(0.0, 0.0, 0.0), vec3(colors.accent.r, colors.accent.g, colors.accent.b), focusUniform);
  material.colorNode = mix(baseTex.rgb, baseTex.rgb.add(accentEdge.mul(0.3)), focusUniform);
  material.opacityNode = baseTex.a;
  material.transparent = true;

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'quote-plane';
  group.add(plane);

  // border/frame accent (thin edge plane behind, tinted ink/surface)
  const frameGeo = new THREE.PlaneGeometry(width + 0.06, height + 0.06);
  const frameMat = new THREE.MeshStandardNodeMaterial();
  frameMat.metalness = 0.5;
  frameMat.roughness = 0.5;
  frameMat.colorNode = mix(
    vec3(colors.ink.r, colors.ink.g, colors.ink.b),
    vec3(colors.accent.r, colors.accent.g, colors.accent.b),
    focusUniform
  );
  const framePlane = new THREE.Mesh(frameGeo, frameMat);
  framePlane.position.z = -0.01;
  framePlane.name = 'quote-frame';
  group.add(framePlane);

  // Attribution label (mono text) beneath quote area
  const attribution = createTextMesh(ctx.fontAtlas, {
    text: '— A. Lindqvist, Collector',
    font: 'text',
    weight: 400,
    size: 0.13,
    color: '#16161d',
    maxWidth: width - 0.4,
    align: 'left',
  });
  attribution.position.set(-width / 2 + 0.25, -height / 2 + 0.2, 0.01);
  attribution.name = 'quote-attribution';
  group.add(attribution);

  // apply cinematic primitives
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      const fn = ctx.primitives[primitive.name];
      if (fn) fn(group, primitive.params);
    });
  }

  // interactions
  const baseY = group.position.y;
  let hoverTl = null;
  let pressTl = null;

  const onPointerOver = () => {
    hoverUniform.value = 1;
    focusUniform.value = 1;
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onPointerOut = () => {
    hoverUniform.value = 0;
    focusUniform.value = 0;
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onClick = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      onComplete: () => {
        gsap.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'power2.out' });
      },
    });

    if (group.userData.emit) {
      group.userData.emit('hub-journal.select', { nodeId: config.id ?? group.name });
    }
  };

  group.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    click: onClick,
  };

  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);

    geometry.dispose();
    frameGeo.dispose();
    material.dispose();
    frameMat.dispose();
    if (tex) tex.dispose();

    if (attribution.geometry) attribution.geometry.dispose();
    if (attribution.material) attribution.material.dispose();
  };

  return group;
}
